"""From the source layers to the generated files' contents (DATA-R75), without writing anything."""

from pathlib import Path

from pagle_data.catalogue import Catalogue, Event, fingerprint
from pagle_data.forever import ForeverLayer, read_forever
from pagle_data.lua import to_lua
from pagle_data.toml_reader import DataError, Problems

CATALOGUE_LUA = "addons/Pagle/data/Catalogue.lua"

# The layers the generator reads, in DATA-R8's order (a later one wins). The baseline and DB2 layers come with
# their own tickets, and data/observed/ in M2.
LAYERS = ("data/forever/",)


def build_catalogue(forever: ForeverLayer) -> Catalogue:
    """The catalogue in its pre-M2 shape (DATA-R79): areas and aliases stay empty until the DB2 and alias layers
    fill them, and nothing confirms an event's weekly rule yet."""
    events: dict[int, Event] = {}
    for event_id, rule in forever.events.items():
        if rule is None:
            events[event_id] = {}
        else:
            events[event_id] = {
                "weekday": rule.weekday,
                "start": rule.start,
                "duration": rule.duration,
                "confirmed": False,
            }
    catalogue: Catalogue = {
        "fingerprint": "",
        "items": {},
        "areas": {},
        "aliases": {},
        "pools": {},
        "windows": {},
        "events": events,
        "fishingSpells": sorted(forever.fishing_spells),
        "auras": sorted(forever.auras),
    }
    catalogue["fingerprint"] = fingerprint(catalogue)
    return catalogue


def header() -> str:
    """DATA-R6: the generator, the source layers, not to be edited by hand, the licence and VMaNGOS."""
    layers = ", ".join(LAYERS)
    return (
        f"-- Generated by scripts/generate-data.py from {layers}."
        " Do not edit by hand: edit data/ and run the generator.\n"
        "-- GPL-3.0-or-later. Contains data derived from the VMaNGOS world database (see NOTICE).\n"
    )


def catalogue_lua(catalogue: Catalogue) -> str:
    """Catalogue.lua (DATA-R76): sets ns.catalogue. Core's TOC lists it before Core's own files."""
    return f"{header()}\n---@class PagleNS\nlocal ns = select(2, ...)\n\nns.catalogue = {to_lua(catalogue)}\n"


def generate(root: Path) -> dict[str, str]:
    """Every generated file's path (relative to root) and content, from root/data/.
    Raises DataError listing every problem found (DATA-R63)."""
    problems = Problems()
    forever = read_forever(root, problems)
    if problems:
        raise DataError(problems.found)
    return {CATALOGUE_LUA: catalogue_lua(build_catalogue(forever))}
